    # Q12 -- points E, F on the secondary diagonal: the inner kite AECF, area ratio, a non-example
    P12 = kite("ABCDO", 12, 9, 40, 25)
    P12["E"] = rot({"e": (0.0, 6.0)}, 25)["e"]
    P12["F"] = rot({"f": (0.0, -6.0)}, 25)["f"]
    l.q(12, u"$ABCD$ הוא דלתון שקודקודי הראש שלו $A$ ו־$C$, ואלכסוניו $AC$ ו־$BD$ נפגשים ב־$O$. הנקודה $E$ על $OB$ והנקודה $F$ על $OD$, שתיהן שונות מ־$O$, ו־$OE=OF$. המרובע $AECF$ מצויר.", [
        I(u"א", u"הוכיחו ש־$AECF$ הוא דלתון קמור שהאלכסון הראשי שלו הוא $AC$.",
          u"בדלתון $ABCD$ האלכסון הראשי $AC$ מאונך ל־$BD$. במשולשים $△AOE$ ו־$△AOF$: $OE=OF$, הזוויות ב־$O$ ישרות ו־$AO$ משותפת, ולכן $AE=AF$; באותו אופן $CE=CF$. אלה שני זוגות נפרדים של צלעות סמוכות שוות. $O$ נמצאת בין $A$ ל־$C$ ובין $E$ ל־$F$, ולכן האלכסונים נחתכים בתוך המרובע והוא קמור. זהו דלתון שקודקודי הראש שלו $A$ ו־$C$, והאלכסון הראשי $AC$.",
          [eq("AE", "AF"), eq("CE", "CF"), sh("kite", "AECF")], space=80),
        I(u"ב", u"הוכיחו שהיחס בין שטח $AECF$ לשטח $ABCD$ שווה ל־$\\f{EF}{BD}$.",
          u"בשני הדלתונים האלכסונים מאונכים והאלכסון $AC$ משותף. לפי נוסחת השטח, שטח $AECF$ הוא $\\f{AC·EF}{2}$ ושטח $ABCD$ הוא $\\f{AC·BD}{2}$, ולכן היחס $\\f{EF}{BD}$.",
          [V(u"יחס השטחים", u"EF/BD")], space=50, on=(u"א",)),
        I(u"ג", u"נתון $AB=15$ ס״מ, $CB=41$ ס״מ ו־$BD=18$ ס״מ. חשבו את שטח $ABCD$, ומצאו את $OE$ כך ששטח $AECF$ יהיה שליש משטח $ABCD$.",
          u"$BO=9$ ס״מ. לפי פיתגורס $AO=\\sqrt{225−81}=12$ ו־$OC=\\sqrt{1681−81}=40$ ס״מ, ולכן $AC=52$ ס״מ והשטח $\\f{52·18}{2}=468$ סמ״ר. לפי ב צריך $EF=\\f{18}{3}=6$ ס״מ, ולכן $OE=3$ ס״מ.",
          [Area("ABCD", 468), F("OE", 3)], space=60, on=(u"ב",), given=[ln("AB", 15), ln("CB", 41), ln("BD", 18)]),
        I(u"ד", u"אילו $E$ ו־$F$ היו על $BD$ משני צדי $O$, אבל $OE$ שונה מ־$OF$, האם $AECF$ היה דלתון? נמקו.",
          u"לא. לפי פיתגורס $AE^2=AO^2+OE^2$ ו־$AF^2=AO^2+OF^2$, ולכן $AE$ שונה מ־$AF$, ובאותו אופן $CE$ שונה מ־$CF$. גם $AE$ קצר מ־$CE$ ו־$AF$ קצר מ־$CF$, כי $AO<OC$. אין אף זוג צלעות סמוכות שוות, ולכן אין זה דלתון.",
          [V(u"הכרעה", u"לא")], space=60, on=(u"א",))],
        fig=fig(P12, "quad.kite+inner-kite-on-secondary-diagonal", polygons=["ABCD", "AECF"],
                segments=["AC", "BD"], size=230),
        given=[sh("kite", "ABCD"), col("AOC"), col("BEO"), col("OFD"), col("BOD"), eq("OE", "OF")])

